-- VFDA VA Quiz App - Invite VA database changes (VA invites, progress per office, deactivation).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after phase7.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261102140000_va_invites.sql =====

-- Invite VA: VFDA invites VAs from the office page, can move a VA to another
-- office, or deactivate them.
--
-- Training progress belongs to the VA *at an office*: day unlocks,
-- certifications and proof of work get an office_id (attempts already have
-- one), so a VA moved to another office starts that office's training fresh
-- and their earlier history stays with the old office. Doctors read progress
-- by office, so the old office's doctor keeps the history and the new one
-- sees only what happens at their office.
--
-- A deactivated profile has no role for row-level security, so it can't read
-- or write anything.
--
-- Safe to run more than once.

alter table public.profiles add column if not exists deactivated_at timestamptz;

create or replace function private.my_role()
returns text
language sql stable security definer
set search_path = ''
as $$
  select role from public.profiles where id = (select auth.uid()) and deactivated_at is null;
$$;

-- office_id on progress rows, filled from the VA's office when not given.
create or replace function private.fill_va_office()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.office_id is null then
    select office_id into new.office_id from public.profiles where id = new.va_id;
  end if;
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['day_unlocks', 'certifications', 'proof_uploads'] loop
    execute format('alter table public.%I add column if not exists office_id uuid references public.offices (id) on delete cascade', t);
    execute format(
      'update public.%I x set office_id = p.office_id from public.profiles p where p.id = x.va_id and x.office_id is null', t);
    -- A row whose VA has no office can't be placed: it belonged to nobody's training.
    execute format('delete from public.%I where office_id is null', t);
    execute format('alter table public.%I alter column office_id set not null', t);
    execute format('create index if not exists %I on public.%I (office_id)', t || '_office_id_idx', t);
    execute format('drop trigger if exists fill_va_office on public.%I', t);
    execute format(
      'create trigger fill_va_office before insert on public.%I for each row execute function private.fill_va_office()', t);
  end loop;
end $$;

-- One row per VA, office and day / workflow.
alter table public.day_unlocks drop constraint if exists day_unlocks_va_id_schedule_day_key;
alter table public.day_unlocks drop constraint if exists day_unlocks_va_office_day;
alter table public.day_unlocks add constraint day_unlocks_va_office_day unique (va_id, office_id, schedule_day);

alter table public.certifications drop constraint if exists certifications_va_id_workflow_key;
alter table public.certifications drop constraint if exists certifications_va_office_workflow;
alter table public.certifications add constraint certifications_va_office_workflow unique (va_id, office_id, workflow);

drop index if exists public.attempts_one_per_day;
create unique index attempts_one_per_day
  on public.attempts (va_id, office_id, schedule_day, version) where kind = 'day';

-- Doctors read progress by office (the office it happened at).
drop policy if exists "doctor reads own VAs' day unlocks" on public.day_unlocks;
create policy "doctor reads own VAs' day unlocks" on public.day_unlocks
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

drop policy if exists "doctor reads own VAs' attempts" on public.attempts;
create policy "doctor reads own VAs' attempts" on public.attempts
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

drop policy if exists "doctor reads own VAs' attempt items" on public.attempt_items;
create policy "doctor reads own VAs' attempt items" on public.attempt_items
  for select to authenticated
  using (exists (
    select 1 from public.attempts a where a.id = attempt_id and private.is_doctor_of_office(a.office_id)
  ));

drop policy if exists "doctor reads own VAs' certifications" on public.certifications;
create policy "doctor reads own VAs' certifications" on public.certifications
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

drop policy if exists "doctor reads own VAs' proof uploads" on public.proof_uploads;
create policy "doctor reads own VAs' proof uploads" on public.proof_uploads
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

drop policy if exists "doctor reads own office reports" on public.notifications;
create policy "doctor reads own office reports" on public.notifications
  for select to authenticated
  using (
    exists (select 1 from public.attempts a where a.id = attempt_id and private.is_doctor_of_office(a.office_id))
    or exists (select 1 from public.certifications c where c.id = certification_id and private.is_doctor_of_office(c.office_id))
  );

-- Proof of work only for a day opened at the VA's current office.
drop policy if exists "va adds own proof uploads" on public.proof_uploads;
create policy "va adds own proof uploads" on public.proof_uploads
  for insert to authenticated
  with check (
    private.is_me_as_va(va_id)
    and status = 'pending'
    and review_note is null
    and reviewed_by is null
    and reviewed_at is null
    and office_id = (select private.my_office_id())
    and (file_path is null
         or file_path like (select private.my_office_id())::text || '/' || (select auth.uid())::text || '/%')
    and exists (
      select 1 from public.day_unlocks u
      where u.va_id = (select auth.uid())
        and u.office_id = proof_uploads.office_id
        and u.schedule_day = proof_uploads.schedule_day
        and u.status <> 'locked'
    )
  );

commit;
